//! The port's framing, profile and rendering against the Python driver's own outputs.
//!
//! `tests/vectors.json` is generated by `tests/gen_vectors.py` from `skynet_canopen.frames` and
//! `skynet_canopen.cia402` — the executable specification's actual bytes and values, never typed
//! in. Every function here must reproduce them exactly. A divergence fails as bytes that differ,
//! not as an axis that moves somewhere else.

use skynet_canopen_rs::cia402::{self, Command, State, Units};
use skynet_canopen_rs::frames::{self, Frame, SdoError};
use skynet_canopen_rs::pyjson;
use skynet_json::Json;

fn vectors() -> Json {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/vectors.json");
    let text = std::fs::read_to_string(path).expect("vectors.json reads");
    Json::parse(&text).expect("vectors.json parses")
}

fn field<'a>(value: &'a Json, key: &str) -> &'a Json {
    value
        .get(key)
        .unwrap_or_else(|| panic!("vectors.json has `{key}`"))
}

fn int(value: &Json, key: &str) -> i64 {
    let number = field(value, key)
        .as_f64()
        .unwrap_or_else(|| panic!("`{key}` is a number"));
    assert_eq!(number.fract(), 0.0, "`{key}` is an integer");
    number as i64
}

fn hex(text: &str) -> Vec<u8> {
    assert!(text.len() % 2 == 0, "{text} is whole bytes");
    text.as_bytes()
        .chunks(2)
        .map(|pair| u8::from_str_radix(std::str::from_utf8(pair).unwrap(), 16).expect("hex"))
        .collect()
}

/// A `{"id", "data"}` object as a frame.
fn frame(value: &Json) -> Frame {
    let id = int(value, "id") as u16;
    let data = hex(field(value, "data").as_str().expect("data is hex"));
    Frame::new(id, &data).expect("a classic CAN frame")
}

#[test]
fn cob_ids_are_cia_301s() {
    let vectors = vectors();
    let ids = field(&vectors, "cob_ids");
    let node = int(ids, "node") as u8;
    assert_eq!(frames::emcy_id(node) as i64, int(ids, "emcy"));
    assert_eq!(frames::tpdo2_id(node) as i64, int(ids, "tpdo2"));
    assert_eq!(frames::rpdo2_id(node) as i64, int(ids, "rpdo2"));
    assert_eq!(frames::sdo_request_id(node) as i64, int(ids, "sdo_request"));
    assert_eq!(
        frames::sdo_response_id(node) as i64,
        int(ids, "sdo_response")
    );
    assert_eq!(frames::heartbeat_id(node) as i64, int(ids, "heartbeat"));
    assert_eq!(frames::SYNC_ID as i64, int(ids, "sync"));
    assert_eq!(frames::NMT_ID as i64, int(ids, "nmt"));
}

#[test]
fn requests_pack_as_the_python_driver_packs_them() {
    let vectors = vectors();
    let requests = field(&vectors, "requests");
    let expect = |name: &str, packed: Frame| {
        assert_eq!(packed, frame(field(requests, name)), "{name}");
    };
    expect(
        "upload_statusword",
        frames::sdo_upload_request(1, 0x6041, 0),
    );
    expect(
        "upload_encoder_revolutions",
        frames::sdo_upload_request(3, 0x608F, 2),
    );
    expect(
        "download_controlword",
        frames::sdo_download_request(2, 0x6040, 0, 0x000F, 2).unwrap(),
    );
    expect(
        "download_mode_csp",
        frames::sdo_download_request(4, 0x6060, 0, 8, 1).unwrap(),
    );
    expect(
        "download_mode_negative",
        frames::sdo_download_request(4, 0x6060, 0, -3, 1).unwrap(),
    );
    expect(
        "download_target_negative",
        frames::sdo_download_request(7, 0x607A, 0, -123456, 4).unwrap(),
    );
    expect("rpdo2_enable", frames::rpdo2(1, 0x000F, -4194304));
    expect("rpdo2_quick_stop", frames::rpdo2(3, 0x0002, 65536));
    expect("nmt_start_node", frames::nmt(frames::NMT_START, 2));
    expect(
        "nmt_pre_operational_all",
        frames::nmt(frames::NMT_PRE_OPERATIONAL, 0),
    );
}

#[test]
fn replies_parse_to_the_python_driver_s_values() {
    let vectors = vectors();
    let replies = field(&vectors, "replies").as_arr().expect("replies");
    assert_eq!(replies.len(), 5);
    for reply in replies {
        let name = field(reply, "name").as_str().unwrap();
        let parsed = frames::parse_sdo_response(
            frame(field(reply, "frame")).payload(),
            int(reply, "index") as u16,
            int(reply, "subindex") as u8,
        )
        .unwrap_or_else(|error| panic!("{name}: {error}"));
        match field(reply, "value") {
            Json::Null => assert_eq!(parsed, None, "{name} is a download acknowledgement"),
            _ => assert_eq!(parsed.map(i64::from), Some(int(reply, "value")), "{name}"),
        }
    }

    let abort = field(&vectors, "abort");
    let error = frames::parse_sdo_response(
        frame(field(abort, "frame")).payload(),
        int(abort, "index") as u16,
        int(abort, "subindex") as u8,
    )
    .expect_err("an abort is not a value");
    assert_eq!(
        error,
        SdoError::Abort {
            index: int(abort, "index") as u16,
            subindex: int(abort, "subindex") as u8,
            code: int(abort, "code") as u32,
        }
    );
    assert_eq!(
        error.explain(),
        field(abort, "explain").as_str().unwrap(),
        "the refusal reads as SdoAbort.explain() does"
    );
}

#[test]
fn tpdo2_parses_as_the_python_driver_parses_it() {
    let vectors = vectors();
    for case in field(&vectors, "tpdo2").as_arr().expect("tpdo2") {
        let parsed = field(case, "parsed").as_arr().expect("a pair");
        let expected = (
            parsed[0].as_f64().unwrap() as u16,
            parsed[1].as_f64().unwrap() as i32,
        );
        let got = frames::parse_tpdo2(frame(field(case, "frame")).payload());
        assert_eq!(got, Some(expected));
        // And the RPDO2 packer, which shares the layout, packs the same bytes back.
        let packed = frames::rpdo2(0, expected.0, expected.1);
        assert_eq!(packed.payload(), frame(field(case, "frame")).payload());
    }
}

#[test]
fn every_statusword_decodes_to_the_python_state() {
    let vectors = vectors();
    let states = field(&vectors, "states").as_arr().expect("states");
    assert_eq!(states.len(), 16, "eight states, with and without voltage");
    for case in states {
        let word = int(case, "statusword") as u16;
        assert_eq!(
            cia402::state_of(word).as_str(),
            field(case, "decoded").as_str().unwrap(),
            "statusword {word:#06x}"
        );
    }
    // The ordering hazard the module header names, held on its own.
    assert_eq!(cia402::state_of(0x0237), State::OperationEnabled);
}

#[test]
fn every_controlword_is_the_python_one() {
    let vectors = vectors();
    let words = field(&vectors, "controlwords")
        .as_obj()
        .expect("controlwords");
    let commands = [
        Command::Shutdown,
        Command::SwitchOn,
        Command::DisableVoltage,
        Command::QuickStop,
        Command::DisableOperation,
        Command::EnableOperation,
        Command::FaultReset,
    ];
    assert_eq!(words.len(), commands.len(), "every command in the profile");
    for command in commands {
        let expected = words
            .get(command.as_str())
            .and_then(Json::as_f64)
            .unwrap_or_else(|| panic!("{} has a controlword", command.as_str()));
        assert_eq!(
            command.controlword() as f64,
            expected,
            "{}",
            command.as_str()
        );
    }
}

#[test]
fn units_agree_bit_for_bit() {
    let vectors = vectors();
    let cases = field(&vectors, "units").as_arr().expect("units");
    assert!(cases.len() >= 20);
    for case in cases {
        let ratio = field(case, "ratio").as_arr().unwrap();
        let units = Units {
            increments: ratio[0].as_f64().unwrap() as i64,
            revolutions: ratio[1].as_f64().unwrap() as i64,
            gear_motor: ratio[2].as_f64().unwrap() as i64,
            gear_shaft: ratio[3].as_f64().unwrap() as i64,
        };
        if case.get("counts").is_some() {
            let radians = units.to_rad(int(case, "counts")).unwrap();
            let expected = field(case, "radians").as_f64().unwrap();
            assert_eq!(
                radians.to_bits(),
                expected.to_bits(),
                "{} counts through {:?}",
                int(case, "counts"),
                units
            );
            assert_eq!(units.to_increments(radians), Some(int(case, "back")));
        } else {
            let radians = field(case, "radians_in").as_f64().unwrap();
            assert_eq!(
                units.to_increments(radians),
                Some(int(case, "counts_out")),
                "{radians} rad through {units:?}"
            );
        }
    }
}

#[test]
fn numbers_render_as_json_dumps_renders_them() {
    let vectors = vectors();
    let cases = field(&vectors, "json_numbers")
        .as_arr()
        .expect("json_numbers");
    for case in cases {
        let value = field(case, "value").as_f64().unwrap();
        assert_eq!(
            pyjson::number(value).as_deref(),
            field(case, "text").as_str(),
            "{value:e}"
        );
    }
}

#[test]
fn strings_render_as_json_dumps_renders_them() {
    let vectors = vectors();
    for case in field(&vectors, "json_strings")
        .as_arr()
        .expect("json_strings")
    {
        let value = field(case, "value").as_str().unwrap();
        assert_eq!(
            pyjson::string(value),
            field(case, "text").as_str().unwrap(),
            "{value:?}"
        );
    }
}
